<script setup lang="ts">
import {computed,onBeforeUnmount,ref,shallowRef} from 'vue';
import {useEditor} from '../stores/editor';
import {importModel} from '../assets/importer';
import type {AssetRecord} from '../domain/types';
import ModelPreview from './ModelPreview.vue';
const e=useEditor(),opened=ref(false),files=shallowRef<File[]>([]),main=ref(''),scale=ref(1),rx=ref(0),ry=ref(0),rz=ref(0),result=shallowRef<AssetRecord>(),progress=ref(''),error=ref(''),busy=ref(false),saving=ref(false);let controller:AbortController|undefined;
const models=computed(()=>files.value.filter(f=>/\.(fbx|glb|gltf)$/i.test(f.name)));
function choose(event:Event){files.value=Array.from((event.target as HTMLInputElement).files??[]);main.value=models.value[0]?.name??'';result.value=undefined;error.value='';}
function reset(){result.value=undefined;}
async function analyze(){controller?.abort();controller=new AbortController();busy.value=true;error.value='';result.value=undefined;try{result.value=await importModel(files.value,main.value,{scale:scale.value,rotation:[rx.value,ry.value,rz.value],signal:controller.signal,onProgress:s=>progress.value=s});}catch(e){if((e as Error).name!=='AbortError')error.value=(e as Error).message;}finally{busy.value=false;progress.value='';}}
async function confirm(){if(!result.value)return;saving.value=true;try{await e.addAsset(result.value);result.value=undefined;opened.value=false;}catch(e){error.value=(e as Error).message;}finally{saving.value=false;}}
function close(){controller?.abort();opened.value=false;result.value=undefined;}
onBeforeUnmount(()=>controller?.abort());
</script>
<template><button class="wide" @click="opened=true">Импорт FBX / GLB</button><Teleport to="body"><div v-if="opened" class="modal-backdrop"><section class="import-dialog" role="dialog" aria-modal="true" aria-label="Импорт модели"><div class="section-heading"><h2>Добавить свою модель</h2><button :disabled="saving" @click="close">Закрыть</button></div><p>Выберите FBX, GLB или glTF вместе с внешними текстурами и BIN. Обработка выполняется на этом устройстве; файлы никуда не отправляются.</p><fieldset :disabled="busy||saving"><label>Модель и связанные файлы<input type="file" multiple @change="choose"></label><label>Основная модель<select v-model="main" @change="reset"><option v-for="f in models" :value="f.name">{{f.name}}</option></select></label><div class="import-fields"><label>Масштаб<input type="number" min="0.0001" max="10000" step="0.01" v-model.number="scale" @input="reset"></label><label v-for="(value,i) in [rx,ry,rz]">{{['Поворот X, °','Поворот Y, °','Поворот Z, °'][i]}}<select :value="value" @change="(event:Event)=>{const n=Number((event.target as HTMLSelectElement).value);if(i===0)rx=n;else if(i===1)ry=n;else rz=n;reset();}"><option v-for="angle in [0,90,180,270]" :value="angle">{{angle}}</option></select></label></div><button :disabled="!main" @click="analyze">Подготовить предпросмотр</button></fieldset><p v-if="busy" role="status">{{progress}} <button @click="controller?.abort()">Отменить импорт</button></p><p v-if="error" role="alert" class="warnings">{{error}}</p><template v-if="result"><ModelPreview :blob="result.glb!"/><label>Название модели<input v-model="result.name"></label><p v-if="result.stats" data-testid="import-dimensions">Ширина {{result.stats.bounds[0].toFixed(3)}} × высота {{result.stats.bounds[1].toFixed(3)}} × глубина {{result.stats.bounds[2].toFixed(3)}} м · {{result.stats.triangles.toLocaleString('ru')}} треугольников</p><p class="hint">Проверьте размеры и ориентацию. Сохраняются оригинал, полная и облегчённая модели. Проигрывание анимаций и редактирование конструкции импортированной мебели пока недоступны. Неподдержанные эффекты материалов могут отличаться.</p><ul v-if="result.warnings.length" class="warnings"><li v-for="warning in result.warnings">{{warning}}</li></ul><button class="primary" :disabled="saving||!result.name.trim()" @click="confirm">{{saving?'Сохранение…':'Добавить в каталог'}}</button></template></section></div></Teleport></template>
